mapper.select:
select mn.*, rwi.* from Outline_Project_Risk mn left join risk_warn_index rwi on rwi.rwi_id = mn.Risk_Id where mn.Opl_Id in
#{item}
order by mn.Opr_Sort

select
mn.*,
rwi.*
from Outline_Project_Risk mn
left join risk_warn_index rwi on rwi.rwi_id = mn.Risk_Id

    
        and mn.id = #{params.id}
    
    
        and mn.Risk_Id = #{params.riskId}
    
    
        and mn.Opl_Id = #{params.oplId}
    

order by mn.Opr_Sort

select mn.*, opl.Opm_Id,rw.* from Outline_Project_Risk mn left join Outline_Project_Lib opl on opl.id = mn.Opl_Id left join Outline_Project_Manage opm on opl.Opm_Id = opm.id left join Risk_Warn rw on rw.Rwi_Id = mn.Risk_Id and rw.P_Id = opm.P_Id where rw.Rw_Id is not null and opl.Opm_Id in
#{item}
and mn.id in ( select min(mn2.id) from Outline_Project_Risk mn2 left join Outline_Project_Lib opl2 on opl2.id = mn2.Opl_Id left join Outline_Project_Manage opm2 on opl2.Opm_Id = opm2.id left join Risk_Warn rw2 on rw2.Rwi_Id = mn2.Risk_Id and rw2.P_Id = opm2.P_Id where rw2.Rw_Id is not null and opl2.Opm_Id in
#{item}
group by rw2.Rw_Id)
